  FROM (SELECT 'SCP0111' MNU_ID, 'Supply_Plan' UPPR_MNU_ID, 'integration-psi' MNU_URL, NULL SYS_MNUL_URL, 'MNU00107' MNU_MSG_ID, 'Integration PSI' MNU_DESC, 111 SORT_ORD, 3 MNU_LV_NO, 'SCREEN' MNU_TP_CD, 'S' UNIT_TP_CD, 'Y' USE_YN, 'NSCM' N01_ATR_CTN, NULL N02_ATR_CTN, NULL N03_ATR_CTN, NULL N04_ATR_CTN, NULL N05_ATR_CTN, NULL N06_ATR_CTN, NULL N07_ATR_CTN, NULL N08_ATR_CTN, NULL N09_ATR_CTN, NULL N10_ATR_CTN, 'supply/integration-psi' ROUTE_PATH FROM DUAL) S
