/* ── SCM_ADM_MSG_M — 문구(MSG/LBL/MNU) — INSERT NOT EXISTS 전용(#140) · insert · 키 MSG_ID, LANG_CD (논리 키(MSG_ID, LANG_CD)) · 3행 */
/*   사내에서 사라진 행 3건(직전 이관 대비) — 클라우드 정리 필요 여부 확인, 자동 삭제 안 함:
     MNU_SCP0111|CN
     MNU_SCP0111|EN
     MNU_SCP0111|KO
*/
INSERT INTO SCM_MGR.SCM_ADM_MSG_M (MSG_ID, LANG_CD, MSG_NM, MSG_DESC, MSG_TP_CD, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.MSG_ID, S.LANG_CD, S.MSG_NM, S.MSG_DESC, S.MSG_TP_CD, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'MNU00107' MSG_ID, 'CN' LANG_CD, 'Integration PSI' MSG_NM, NULL MSG_DESC, 'MNU' MSG_TP_CD, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_MSG_M T WHERE NVL(TO_CHAR(T.MSG_ID), '~') = NVL(TO_CHAR(S.MSG_ID), '~') AND NVL(TO_CHAR(T.LANG_CD), '~') = NVL(TO_CHAR(S.LANG_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_MSG_M (MSG_ID, LANG_CD, MSG_NM, MSG_DESC, MSG_TP_CD, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.MSG_ID, S.LANG_CD, S.MSG_NM, S.MSG_DESC, S.MSG_TP_CD, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'MNU00107' MSG_ID, 'EN' LANG_CD, 'Integration PSI' MSG_NM, NULL MSG_DESC, 'MNU' MSG_TP_CD, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_MSG_M T WHERE NVL(TO_CHAR(T.MSG_ID), '~') = NVL(TO_CHAR(S.MSG_ID), '~') AND NVL(TO_CHAR(T.LANG_CD), '~') = NVL(TO_CHAR(S.LANG_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_MSG_M (MSG_ID, LANG_CD, MSG_NM, MSG_DESC, MSG_TP_CD, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.MSG_ID, S.LANG_CD, S.MSG_NM, S.MSG_DESC, S.MSG_TP_CD, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'MNU00107' MSG_ID, 'KO' LANG_CD, 'Integration PSI' MSG_NM, NULL MSG_DESC, 'MNU' MSG_TP_CD, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_MSG_M T WHERE NVL(TO_CHAR(T.MSG_ID), '~') = NVL(TO_CHAR(S.MSG_ID), '~') AND NVL(TO_CHAR(T.LANG_CD), '~') = NVL(TO_CHAR(S.LANG_CD), '~'));

/* ── SCM_ADM_CMBO_SQL_M — 콤보 SQL(공용) — 없을 때만 · insert · 키 SQL_ID, MDU_DIVS_CD (PK) · 1행 */
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'DATE_WEEKLY1_SCP_ALL' SQL_ID, 'ALL' MDU_DIVS_CD, '[SCP_ALL] AS-IS UP_FX_GetCommonDataList_SCP_ALL @Code=''DATE_WEEKLY1''' SQL_NM, CHR(13) || CHR(10) || 'SELECT A.PLAN_START_YYYYMMDD AS CODE' || CHR(13) || CHR(10) || '     , CASE WHEN C.FP_TARGET_YN = ''Y''' || CHR(13) || CHR(10) || '            THEN TO_CHAR(FN_CHAR_TO_DATE(A.PLAN_START_YYYYMMDD), ''YYYY-MM-DD'') || '' ('' || B.WEEK_NAME || '')''' || CHR(13) || CHR(10) || '            ELSE TO_CHAR(FN_CHAR_TO_DATE(A.PLAN_START_YYYYMMDD), ''YYYY-MM-DD'') || '' ('' || B.WEEK_NAME || '')'' || '' (No Plan)''' || CHR(13) || CHR(10) || '       END AS NAME' || CHR(13) || CHR(10) || '     , A.DIVISION_ID' || CHR(13) || CHR(10) || '     , SUBSTR(D.HORIZON_END_DATE, 1, 8) AS HORIZON_END_DATE /* Plan Horizon 종료일 */' || CHR(13) || CHR(10) || '     , CEIL((TO_DATE(SUBSTR(D.HORIZON_END_DATE, 1, 8), ''YYYYMMDD'') - TO_DATE(A.PLAN_START_YYYYMMDD, ''YYYYMMDD'') + 1) / 7) AS PLAN_WEEKS /* Plan Date ~ Horizon End 주차 수 */' || CHR(13) || CHR(10) || '     , CASE WHEN CEIL((TO_DATE(SUBSTR(D.HORIZON_END_DATE, 1, 8), ''YYYYMMDD'') - TO_DATE(A.PLAN_START_YYYYMMDD, ''YYYYMMDD'') + 1) / 7) > 52' || CHR(13) || CHR(10) || '            THEN ''Y''' || CHR(13) || CHR(10) || '            ELSE ''N''' || CHR(13) || CHR(10) || '       END AS OVER_52W_YN /* 52주 초과 여부 : Y 이면 W82 버튼 표시 */' || CHR(13) || CHR(10) || '  FROM SCP_PLAN_VERSION_V A' || CHR(13) || CHR(10) || '     , SCM_SYS_CALENDAR_M B' || CHR(13) || CHR(10) || '     , ( SELECT IA.DIVISION_ID' || CHR(13) || CHR(10) || '              , IA.PLAN_START_YYYYMMDD' || CHR(13) || CHR(10) || '              , IA.FP_TARGET_YN' || CHR(13) || CHR(10) || '           FROM SCP_PLN_INTERFACE_YN IA' || CHR(13) || CHR(10) || '          WHERE ( @divisionId IS NULL OR IA.DIVISION_ID IN (SELECT VALUE FROM FN_SplitString(@divisionId, '','')) )' || CHR(13) || CHR(10) || '       ) C' || CHR(13) || CHR(10) || '     , SCM_MST_PLAN D' || CHR(13) || CHR(10) || ' WHERE B.BASIS_YYYYMMDD = A.PLAN_START_YYYYMMDD' || CHR(13) || CHR(10) || '   AND C.PLAN_START_YYYYMMDD(+) = A.PLAN_START_YYYYMMDD' || CHR(13) || CHR(10) || '   AND C.DIVISION_ID(+) = A.DIVISION_ID' || CHR(13) || CHR(10) || '   AND D.DIVISION_ID(+) = A.DIVISION_ID' || CHR(13) || CHR(10) || '   AND D.PLAN_ID(+) = A.PLAN_ID' || CHR(13) || CHR(10) || '   AND ( @divisionId IS NULL OR A.DIVISION_ID = @divisionId )' || CHR(13) || CHR(10) || '   AND ( @versionId IS NULL OR A.VERSION_ID = @versionId )' || CHR(13) || CHR(10) || ' GROUP BY A.PLAN_START_YYYYMMDD' || CHR(13) || CHR(10) || '        , B.WEEK_NAME' || CHR(13) || CHR(10) || '        , C.FP_TARGET_YN' || CHR(13) || CHR(10) || '        , A.DIVISION_ID' || CHR(13) || CHR(10) || '        , D.HORIZON_END_DATE' || CHR(13) || CHR(10) || ' ORDER BY UPPER(A.PLAN_START_YYYYMMDD) DESC' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));

COMMIT;
